474	
475	```javascript
476	// Function words that would otherwise crowd every ranking. The list is
477	// deliberately short and fixed: callers who need a different list can filter
478	// the full ranking (pass a large n) themselves.
479	const STOP_WORDS = new Set([
480	  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'for', 'from', 'had', 'has',
481	  'have', 'he', 'her', 'his', 'i', 'in', 'is', 'it', 'its', 'of', 'on', 'or',
482	  'she', 'that', 'the', 'their', 'there', 'they', 'this', 'to', 'was', 'were',
483	  'will', 'with',
484	]);
485	
486	/**
487	 * List the most frequent words in a piece of text.
488	 *
489	 * Words are lower-cased, typographic apostrophes are folded to straight ones,
490	 * and stop words are skipped. Entries are ordered by count (highest first),
491	 * then alphabetically, so the result is deterministic.
492	 *
493	 * @param {string} text
494	 * @param {number} n How many entries to return; a non-negative integer.
495	 * @returns {Array<{word: string, count: number}>}
496	 */
497	function topWords(text, n) {
498	  assertText('topWords', text);
499	  if (!Number.isInteger(n) || n < 0) {
500	    throw new RangeError(`topWords: n must be a non-negative integer, received ${String(n)}`);
501	  }
502	  const counts = new Map();
503	  for (const token of tokenize(text)) {
504	    const word = token.toLowerCase().replace(/’/g, "'");
505	    if (STOP_WORDS.has(word)) {
506	      continue;
507	    }
508	    counts.set(word, (counts.get(word) ?? 0) + 1);
509	  }
510	  return [...counts]
511	    .map(([word, count]) => ({ word, count }))
512	    .sort((a, b) => b.count - a.count || (a.word < b.word ? -1 : a.word > b.word ? 1 : 0))
513	    .slice(0, n);
514	}
515	
516	module.exports = { wordCount, sentenceCount, topWords };
517	```
