746	// Function words that would otherwise crowd every ranking. The list is
747	// deliberately short and fixed: callers who need a different list can filter
748	// the full ranking (pass a large n) themselves.
749	const STOP_WORDS = new Set([
750	  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'for', 'from', 'had', 'has',
751	  'have', 'he', 'her', 'his', 'i', 'in', 'is', 'it', 'its', 'of', 'on', 'or',
752	  'she', 'that', 'the', 'their', 'there', 'they', 'this', 'to', 'was', 'were',
753	  'will', 'with',
754	]);
755	
756	/**
757	 * List the most frequent words in a piece of text.
758	 *
759	 * Words are lower-cased, typographic apostrophes are folded to straight ones,
760	 * and stop words are skipped. Entries are ordered by count (highest first),
761	 * then alphabetically, so the result is deterministic.
762	 *
763	 * @param {string} text
764	 * @param {number} n How many entries to return; a non-negative integer.
765	 * @returns {Array<{word: string, count: number}>}
766	 */
767	function topWords(text, n) {
768	  assertText('topWords', text);
769	  if (!Number.isInteger(n) || n < 0) {
770	    throw new RangeError(`topWords: n must be a non-negative integer, received ${String(n)}`);
771	  }
772	  const counts = new Map();
773	  for (const token of tokenize(text)) {
774	    const word = token.toLowerCase().replace(/’/g, "'");
775	    if (STOP_WORDS.has(word)) {
776	      continue;
777	    }
778	    counts.set(word, (counts.get(word) ?? 0) + 1);
779	  }
780	  return [...counts]
781	    .map(([word, count]) => ({ word, count }))
782	    .sort((a, b) => b.count - a.count || (a.word < b.word ? -1 : a.word > b.word ? 1 : 0))
783	    .slice(0, n);
784	}
