790	 *
791	 * The estimate is the word count divided by the reading rate, rounded up, so
792	 * any text with at least one word takes at least a minute and the empty text
793	 * takes none.
794	 *
795	 * @param {string} text
796	 * @param {number} [wpm=200] Reading rate in words per minute; a positive, finite number.
797	 * @returns {number} Whole minutes.
798	 */
799	function readingTimeMinutes(text, wpm = DEFAULT_WORDS_PER_MINUTE) {
800	  assertText('readingTimeMinutes', text);
801	  if (typeof wpm !== 'number' || !Number.isFinite(wpm) || wpm <= 0) {
802	    throw new RangeError(`readingTimeMinutes: wpm must be a positive finite number, received ${String(wpm)}`);
803	  }
804	  return Math.ceil(wordCount(text) / wpm);
